import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"URI 通訊協定（lertaro://）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/uri-protocol.md","filePath":"zh-TW/user-guide/uri-protocol.md","lastUpdated":1787586465000}'),l={name:"zh-TW/user-guide/uri-protocol.md"};function i(o,e,r,d,p,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="uri-通訊協定-lertaro" tabindex="-1">URI 通訊協定（lertaro://） <a class="header-anchor" href="#uri-通訊協定-lertaro" aria-label="Permalink to &quot;URI 通訊協定（lertaro://）&quot;">​</a></h1><p>Lertaro 在首次執行時會自動在 Windows 系統中註冊自訂通訊協定 <strong><code>lertaro://</code></strong>。無論是網頁超連結、桌面捷徑、自動化指令碼還是第三方軟體，均可透過該通訊協定直接喚起 Lertaro 的特定搜尋、直達設定頁面或發起跨裝置傳輸。</p><h2 id="_1-通訊協定機制與執行個體路由" tabindex="-1">1. 通訊協定機制與執行個體路由 <a class="header-anchor" href="#_1-通訊協定機制與執行個體路由" aria-label="Permalink to &quot;1. 通訊協定機制與執行個體路由&quot;">​</a></h2><ul><li><strong>開箱即用</strong>：無需手動設定登錄檔，Lertaro 啟動時會自動完成註冊與自癒校驗。</li><li><strong>單一執行個體路由</strong>：若 Lertaro 已經在背景執行，開啟 <code>lertaro://</code> 連結會直接喚醒目前執行中的前景執行個體，絕不會重複啟動多個處理程序；若 Lertaro 尚未啟動，系統會自動拉起主程式並立即執行連結指定的動作。</li></ul><h2 id="_2-完整-uri-路由指令表" tabindex="-1">2. 完整 URI 路由指令表 <a class="header-anchor" href="#_2-完整-uri-路由指令表" aria-label="Permalink to &quot;2. 完整 URI 路由指令表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">URI 指令格式</th><th style="text-align:left;">功能說明與互動效果</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">啟用並顯示快速搜尋視窗（效果等同於按兩下 <code>Ctrl</code> 全域快速鍵）。</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[關鍵字]</code></td><td style="text-align:left;">啟用快速搜尋視窗，並預先填入指定的 <code>[關鍵字]</code> 並立即過濾。</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[關鍵字]</code></td><td style="text-align:left;">開啟大尺寸完整搜尋主視窗，並預先填入指定的 <code>[關鍵字]</code>。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[分區]</code></td><td style="text-align:left;">開啟設定視窗，並直接切換到指定的分區索引標籤頁。</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[序號]</code></td><td style="text-align:left;">開啟設定視窗並精準跳轉到某項具體設定項目，同時閃爍反白該選項。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">開啟空白的 LocalSend 區域網路傳送視窗。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[編碼後的絕對路徑...]</code></td><td style="text-align:left;">開啟 LocalSend 並切換至檔案模式，自動新增一個或多個目標檔案/目錄。</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[編碼後的文字]</code></td><td style="text-align:left;">開啟 LocalSend 並切換至文字模式，自動填入指定的待傳送文字。</td></tr></tbody></table><h3 id="設定分區參數-分區" tabindex="-1">設定分區參數 <code>[分區]</code> <a class="header-anchor" href="#設定分區參數-分區" aria-label="Permalink to &quot;設定分區參數 \`[分區]\`&quot;">​</a></h3><p>設定分區參數不區分大小寫，對應設定介面的側邊欄模組：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - 執行狀態</span></span>
<span class="line"><span>Index        - 索引設定</span></span>
<span class="line"><span>General      - 一般設定</span></span>
<span class="line"><span>Appearance   - 外觀與主題</span></span>
<span class="line"><span>Hotkeys      - 快速鍵設定</span></span>
<span class="line"><span>Plugins      - 外掛模組管理</span></span>
<span class="line"><span>Favorites    - 我的最愛</span></span>
<span class="line"><span>History      - 搜尋歷程記錄</span></span>
<span class="line"><span>QuickPanel   - 快速面板</span></span>
<span class="line"><span>About        - 關於與更新</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><code>lertaro://settings/entry/[序號]</code> 中的序號是由內建的<a href="./instant-answers.html#2-關鍵字觸發功能內建外掛模組"><strong>設定搜尋</strong></a>功能動態產生的。由於內部序號在版本更新或重啟後可能會重新分配，建議在外部指令碼中優先使用 <code>lertaro://settings/page/[分區]</code>。</p></div><h2 id="_3-localsend-路由與參數編碼規範" tabindex="-1">3. LocalSend 路由與參數編碼規範 <a class="header-anchor" href="#_3-localsend-路由與參數編碼規範" aria-label="Permalink to &quot;3. LocalSend 路由與參數編碼規範&quot;">​</a></h2><p>在使用 LocalSend 相關 URI 時，每個檔案路徑或文字必須進行標準的 URL 編碼（例如將 <code>:</code> 轉換為 <code>%3A</code>，將 <code>\\</code> 轉換為 <code>%5C</code>，將空格轉換為 <code>%20</code>）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 預填多個檔案路徑</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 預填待傳送文字</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>安全條件約束</strong>：所有傳入的檔案路徑必須為本機已經真實存在的絕對路徑；帶有預填內容的連結僅會開啟 LocalSend 並進入裝置選取介面，絕不會自動向任何裝置傳送資料。</li></ul><h2 id="_4-外部聯動實戰範例" tabindex="-1">4. 外部聯動實戰範例 <a class="header-anchor" href="#_4-外部聯動實戰範例" aria-label="Permalink to &quot;4. 外部聯動實戰範例&quot;">​</a></h2><h3 id="瀏覽器與-markdown-連結" tabindex="-1">瀏覽器與 Markdown 連結 <a class="header-anchor" href="#瀏覽器與-markdown-連結" aria-label="Permalink to &quot;瀏覽器與 Markdown 連結&quot;">​</a></h3><p>在個人知識庫（如 Obsidian、Notion 或 Markdown 文件）中直接插入超連結：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">點擊開啟 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Lertaro 外觀設定</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">點擊快速尋找 [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">專案財務報表</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/財務報表%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="windows-捷徑與批次處理" tabindex="-1">Windows 捷徑與批次處理 <a class="header-anchor" href="#windows-捷徑與批次處理" aria-label="Permalink to &quot;Windows 捷徑與批次處理&quot;">​</a></h3><p>在桌面右鍵新建捷徑，在物件位置輸入：</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>在 PowerShell 指令碼中呼叫：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-安全性與未知路由容錯" tabindex="-1">5. 安全性與未知路由容錯 <a class="header-anchor" href="#_5-安全性與未知路由容錯" aria-label="Permalink to &quot;5. 安全性與未知路由容錯&quot;">​</a></h2><ul><li><strong>無訊息容錯</strong>：由於任何外部網頁或指令碼均可嘗試觸發該通訊協定，Lertaro 對所有傳入的 URI 實行嚴格的白名單校驗。若連結格式錯誤、拼寫有誤或指向不存在的路由，Lertaro 會直接安全忽略，僅記錄偵錯記錄，絕不會產生意外的破壞性操作或當機。</li></ul>`,25)])])}const k=a(l,[["render",i]]);export{g as __pageData,k as default};
